iiActorObject::TemplateRigTransferOptions options;
options.skin = iiActorObject::TemplateRigSkin::ClosestSurface;
options.anchors = iiActorObject::TemplateRigAnchorMethod::ProjectSurface;
options.projection.registration = iiActorObject::TemplateRigRegistration::AxisAlignedBounds;
options.projection.maximumSurfaceDistance = .05; // 오브젝트 좌표 단위
auto fitted = characterTemplate.rigMesh(staticMesh, options);
